$page_title = $product['name']; $active_page='catalog';
$pros = preg_split('/\r\n|\r|\n/', (string)$product['pros']); $cons = preg_split('/\r\n|\r|\n/', (string)$product['cons']);
$cases = case_labels($product['use_cases']);
require __DIR__ . '/includes/header.php';
?>
