  <div class="pros-cons"><div><strong><span style="color:#56803a">↗</span> Yang menarik</strong><?php $hasPros=false; foreach($pros as $item) if(trim($item)!==''){ $hasPros=true; echo '<p>+ '.h(trim($item)).'</p>'; } if(!$hasPros) echo '<p>Belum ada catatan kelebihan.</p>'; ?></div><div><strong><span style="color:var(--orange)">↘</span> Yang perlu dicek</strong><?php $hasCons=false; foreach($cons as $item) if(trim($item)!==''){ $hasCons=true; echo '<p>− '.h(trim($item)).'</p>'; } if(!$hasCons) echo '<p>Belum ada catatan kompromi.</p>'; ?></div></div>
